import type { Metadata } from "next";
import { BUSINESS } from "./constants";

interface PageMeta {
  title: string;
  description: string;
  path: string;
}

/** Share image generated by app/opengraph-image.tsx. Listed explicitly because a page's own
 *  openGraph block replaces the root one (and with it the file-based image). */
const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${BUSINESS.name}, ${BUSINESS.tagline}, ${BUSINESS.city}`,
};

/** Per-page metadata with canonical URL, Open Graph and Twitter tags. */
export function pageMetadata({ title, description, path }: PageMeta): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      siteName: BUSINESS.name,
      locale: "en_IN",
      type: "website",
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [OG_IMAGE.url],
    },
  };
}
